    62		// Track the most recent MULHU writeback seen at the datapath.
    63		reg h_wb_pending;
    64		reg [31:0] h_wb_data;
    65		reg [31:0] h_wb_rs1;
    66		reg [31:0] h_wb_rs2;
    67		reg h_wb_rd_zero;
    68		reg [4:0] h_wb_rd;
    69		reg [4:0] h_wb_rs1_addr;
    70		reg [4:0] h_wb_rs2_addr;
    71	
    72	`ifdef RISCV_FORMAL_ALTOPS
    73		localparam [31:0] h_mulhu_altops_mask = 32'h949ce5e8;
    74	`endif
    75	
    76		always @(posedge clock) begin
    77			if (reset) begin
    78				h_wb_pending <= 0;
    79				h_wb_data <= 0;
    80				h_wb_rs1 <= 0;
    81				h_wb_rs2 <= 0;
    82				h_wb_rd_zero <= 0;
    83				h_wb_rd <= 0;
    84				h_wb_rs1_addr <= 0;
    85				h_wb_rs2_addr <= 0;
    86			end else begin
    87				if (dut.cpuregs_write && h_dbg_is_mulhu) begin
    88					h_wb_pending <= 1;
    89					h_wb_data <= (dut.latched_rd != 0) ? dut.cpuregs_wrdata : 0;
    90					h_wb_rs1 <= dut.dbg_rs1val;
    91					h_wb_rs2 <= dut.dbg_rs2val;
    92					h_wb_rd_zero <= (dut.latched_rd == 0);
    93					h_wb_rd <= dut.dbg_insn_opcode[11:7];
    94					h_wb_rs1_addr <= dut.dbg_insn_opcode[19:15];
    95					h_wb_rs2_addr <= dut.dbg_insn_opcode[24:20];
    96				end
    97	
    98				if (rvfi_valid[0] && h_is_mulhu) begin
    99					h_wb_pending <= 0;
   100					// If the instruction decodes as MULHU, it must not be reported as a trap/halt.
   101					no_trap: assert(!rvfi_trap[0]);
   102					no_halt: assert(!rvfi_halt[0]);
   103					// MULHU retirement must observe its writeback.
   104					wb_seen: assert(h_wb_pending);
   105					wb_data_match: assert((rvfi_rd_wdata == h_wb_data));
   106					wb_rs1_match: assert((rvfi_rs1_rdata == h_wb_rs1));
   107					wb_rs2_match: assert((rvfi_rs2_rdata == h_wb_rs2));
   108					wb_rd_match: assert((rvfi_insn[11:7] == h_wb_rd));
   109					wb_rs1_addr_match: assert((rvfi_insn[19:15] == h_wb_rs1_addr));
   110					wb_rs2_addr_match: assert((rvfi_insn[24:20] == h_wb_rs2_addr));
   111					// Stronger (check-independent) form of rd_wdata_match objective.
   112					rd_wdata_match: assert((chk.spec_rd_wdata == rvfi_rd_wdata));
   113					// For 32-bit MULHU, RVFI addresses must match the instruction fields.
   114					rd_addr_match:  assert((rvfi_rd_addr[4:0] == rvfi_insn[11:7]));
   115					rs1_addr_match: assert((rvfi_rs1_addr[4:0] == rvfi_insn[19:15]));
   116					rs2_addr_match: assert((rvfi_rs2_addr[4:0] == rvfi_insn[24:20]));
   117				end
   118	
   119				if (dut.cpuregs_write && h_dbg_is_mulhu) begin
   120					// For MULHU, the retiring instruction must have captured both source operands.
   121					src_captured: assert((dut.dbg_rs1val_valid && dut.dbg_rs2val_valid));
   122					// For MULHU, if a source register is x0 then the captured value must be zero.
   123					rs1_x0_val: assert(!dut.dbg_insn_opcode[19:15] == 5'd0 || (dut.dbg_rs1val == 0));
   124					rs2_x0_val: assert(!dut.dbg_insn_opcode[24:20] == 5'd0 || (dut.dbg_rs2val == 0));
   125					// For MULHU, this is a PCPI instruction (i.e. not handled by the base ALU decode).
   126					instr_flag: assert(dut.instr_trap);
   127					// For MULHU, the retiring writeback data must match the captured operands.
   128	`ifdef RISCV_FORMAL_ALTOPS
   129					wrdata_match: assert(dut.cpuregs_wrdata == ((dut.dbg_rs1val + dut.dbg_rs2val) ^ h_mulhu_altops_mask));
   130	`else
   131					wrdata_match: assert(dut.cpuregs_wrdata == (($unsigned(dut.dbg_rs1val) * $unsigned(dut.dbg_rs2val)) >> 32));
   132	`endif
   133					// MULHU must not be treated as a control-flow change at retirement.
   134					no_branch: assert(!dut.latched_branch);
   135				end
   136	
   137				// PCPI arbitration sanity for MULHU: if the PCPI interface reports "ready" while executing
   138				// a MULHU instruction, it must be coming from the MUL unit (not DIV).
   139				if (h_dbg_is_mulhu && dut.pcpi_int_ready) begin
   140					pcpi_ready_from_mul: assert(dut.pcpi_mul_ready);
   141					pcpi_ready_not_div:  assert(!dut.pcpi_div_ready);
   142					// The instruction presented on the PCPI bus must also decode as MULHU.
   143					pcpi_insn_is_mulhu: assert(h_pcpi_is_mulhu);
   144				end
   145	
   146				wb_consistent: assert(!h_wb_pending ||
   147	`ifdef RISCV_FORMAL_ALTOPS
   148					(h_wb_rd_zero ? (h_wb_data == 0) : (h_wb_data == ((h_wb_rs1 + h_wb_rs2) ^ h_mulhu_altops_mask))));
   149	`else
   150					(h_wb_rd_zero ? (h_wb_data == 0) : (h_wb_data == (($unsigned(h_wb_rs1) * $unsigned(h_wb_rs2)) >> 32))));
   151	`endif
   152				// If the retired instruction has no rd, the reported writeback data must be zero.
   153				addr0_wdata0: assert(!(rvfi_valid[0] && (rvfi_rd_addr[4:0] == 5'd0)) || (rvfi_rd_wdata == 0));
   154			end
   155		end
   156		/// Helper Assertion End
   157	endmodule
